export const defaults={project:PROJECT_ID,version:1,floor:'#beb5a5',wall:'#f5f3ee',cabinet:'#dedbd2',furniture:true,daylight:'day'};
export function validSettings(v){return v?.project===PROJECT_ID&&v.version===1&&['floor','wall','cabinet'].every(k=>/^#[0-9a-f]{6}$/i.test(v[k]))&&typeof v.furniture==='boolean'&&['day','evening'].includes(v.daylight);}
